<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserAccessTemporalCode\Domain\ValueObject\Accessor\UserAccessTemporalCodeFailedLoginAttemptsAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserAccessTemporalCodeFailedLoginAttemptsAccessor trait.
 *
 * Covers null default, string/VO assignment via withFailedLoginAttempts,
 * getFailedLoginAttempts/failedLoginAttempts accessors, and isFailedLoginAttemptsChanged with/without original.
 */
class UserAccessTemporalCodeFailedLoginAttemptsAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withFailedLoginAttempts creates a new instance with the FailedLoginAttempts set
     * from a string value, and getFailedLoginAttempts returns the primitive string.
     */
    public function testWithFailedLoginAttemptsFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeFailedLoginAttemptsAccessorUnitTest();

        // Act
        $result = $holder->withFailedLoginAttempts(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->getFailedLoginAttempts());
    }
    /**
     * Asserts that withfailedLoginAttempts has access to the value object
     * from a string value, and getFailedLoginAttempts returns the primitive string.
     */
    public function testWithFailedLoginAttemptsFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeFailedLoginAttemptsAccessorUnitTest();

        // Act
        $result = $holder->withFailedLoginAttempts(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->failedLoginAttempts()->value());
    }
    public function testChangedFailedLoginAttempts(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeFailedLoginAttemptsAccessorUnitTest();
        $original = $holder->withFailedLoginAttempts( 1);
        $same = $holder->withFailedLoginAttempts( 1);
        $modified = $holder->withFailedLoginAttempts(2);

        // Act
        $unchanged = $holder->isFailedLoginAttemptsChanged();
        $withSame = $original->isFailedLoginAttemptsChanged( $same );
        $withDiferent = $original->isFailedLoginAttemptsChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserAccessTemporalCodeFailedLoginAttemptsAccessorUnitTest
{
  use UserAccessTemporalCodeFailedLoginAttemptsAccessor;
}
